// Graticule Labels (Stereographic) — Geo, route: jsx
// Source: graticule-labels-stereographic
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useId, useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

// Left and right hold the rim labels: 10px of radial push, 6px of gap, then the text.
const MARGIN = { top: 26, right: 46, bottom: 26, left: 46 };

const LONGITUDE = -100;
const graticule = d3.geoGraticule10();
// The visible hemisphere: a 90-degree cap centred on the projection's own centre.
const outline = d3.geoCircle().radius(90).center([LONGITUDE, 0])();

const formatLatitude = (v: number) => `${Math.abs(v)}°${v < 0 ? 'S' : 'N'}`;
const formatLongitude = (v: number) => `${Math.abs(v)}°${v < 0 ? 'W' : 'E'}`;

type Label = { key: string; x: number; y: number; dx: number; anchor: string; text: string };

/** Push a projected point k pixels further out along its ray from the projection centre. */
function pushOut(p: [number, number], centre: [number, number], k: number): [number, number] {
  const dx = p[0] - centre[0];
  const dy = p[1] - centre[1];
  const r = Math.hypot(dx, dy);
  if (r === 0) return p;
  return [p[0] + (dx * k) / r, p[1] + (dy * k) / r];
}

export default function GraticuleLabelsStereographic({ width }: { width: number }) {
  const size = width - MARGIN.left - MARGIN.right;
  const height = size + MARGIN.top + MARGIN.bottom;
  const clipId = useId();

  const map = useMemo(() => {
    if (size <= 0) return null;

    // The cap projects to a circle centred on translate(), so fitting it to a square
    // leaves the rim concentric with the centre the labels are pushed away from.
    const projection = d3
      .geoStereographic()
      .rotate([-LONGITUDE, 0])
      .precision(0.2)
      .fitSize([size, size], outline);
    const path = d3.geoPath(projection);
    const centre = projection.translate();

    // The notebook's 10-degree parallels crowd on a narrow map, and meridians bunch
    // hardest near the centre, so both get thinned below 420px.
    const dense = size >= 420;

    const parallels: Label[] = [];
    // Every parallel meets the rim at the two meridians a quarter turn from centre.
    for (const lat of d3.range(-80, 81, dense ? 10 : 20)) {
      for (const side of [1, -1]) {
        const p = projection([LONGITUDE + 90 * side, lat]);
        if (!p) continue;
        const [x, y] = pushOut(p, centre, 10);
        parallels.push({
          key: `lat-${lat}-${side}`,
          x,
          y,
          dx: 6 * side,
          anchor: side > 0 ? 'start' : 'end',
          text: formatLatitude(lat)
        });
      }
    }

    // Meridians converge on the poles, so the rim gives them no room; the equator does.
    const meridians: Label[] = [];
    for (const lon of d3.range(LONGITUDE - 60, LONGITUDE + 61, dense ? 30 : 60)) {
      const p = projection([lon, 0]);
      if (!p) continue;
      meridians.push({
        key: `lon-${lon}`,
        x: p[0],
        y: p[1] - 5,
        dx: 0,
        anchor: 'middle',
        text: formatLongitude(lon)
      });
    }

    return {
      outline: path(outline) ?? '',
      graticule: path(graticule) ?? '',
      land: path(worldLand) ?? '',
      parallels,
      meridians
    };
  }, [size]);

  if (width === 0 || !map) return null;

  // Rectangle over the whole viewport plus the rim, wound even-odd: everything outside
  // the hemisphere. Its complement is the clip for the near side.
  const outside = `M${-MARGIN.left},${-MARGIN.top}H${width - MARGIN.left}V${
    height - MARGIN.top
  }H${-MARGIN.left}Z${map.outline}`;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Stereographic hemisphere centred on 100 degrees west, with the graticule's parallels labelled along the rim and its meridians along the equator"
    >
      <defs>
        <clipPath id={`${clipId}-in`}>
          <path d={map.outline} />
        </clipPath>
        <clipPath id={`${clipId}-out`}>
          <path d={outside} clipRule="evenodd" />
        </clipPath>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <path d={map.graticule} fill="none" stroke="var(--line)" strokeWidth={0.6} />
        <path d={map.land} clipPath={`url(#${clipId}-in)`} fill="var(--accent)" fillOpacity={0.5} />
        <path
          d={map.land}
          clipPath={`url(#${clipId}-out)`}
          fill="var(--muted)"
          fillOpacity={0.12}
        />
        <path d={map.outline} fill="none" stroke="var(--muted)" strokeWidth={1.2} />
        {/* Labels sit over land on both sides of the rim, so every one gets a knocked-out halo. */}
        <g
          fontSize={10}
          fill="var(--muted)"
          stroke="var(--bg)"
          strokeWidth={2}
          paintOrder="stroke"
        >
          {map.parallels.map((d) => (
            <text key={d.key} x={d.x} y={d.y} dx={d.dx} dy="0.35em" textAnchor={d.anchor}>
              {d.text}
            </text>
          ))}
          {map.meridians.map((d) => (
            <text key={d.key} x={d.x} y={d.y} textAnchor={d.anchor}>
              {d.text}
            </text>
          ))}
        </g>
      </g>
    </svg>
  );
}
